'use strict';

var ZERO_PADDING = "0000000000000000";
function hashOutToHex(h4) {
  var a = ZERO_PADDING + h4[0].toString(16);
  var b = ZERO_PADDING + h4[1].toString(16);
  var c = ZERO_PADDING + h4[2].toString(16);
  var d = ZERO_PADDING + h4[3].toString(16);
  return "0x" + d.substring(d.length - 16) + c.substring(c.length - 16) + b.substring(b.length - 16) + a.substring(a.length - 16);
}

exports.hashOutToHex = hashOutToHex;
